(ns unit.ansible-vault.fixtures
  "Access to fixtures generated by test/integration/gen_ansible_vault_fixtures.clj."
  (:require [babashka.fs :as fs]
            [clojure.edn :as edn]
            [clojure.string :as str]))

(def dir "test-resources/ansible_vault/generated")

(defn path [f] (str (fs/path dir f)))

(def manifest (edn/read-string (slurp (path "manifest.edn"))))

(defn password
  "Effective password of a password file (ansible strips whitespace)."
  [f]
  (str/trim (slurp (path f))))

(defn vault-text [kase] (slurp (path (:vault kase))))

(defn plain-bytes ^bytes [kase] (fs/read-all-bytes (path (:plain kase))))

(defn kase [name]
  (first (filter #(= name (:name %)) (:cases manifest))))
